/**
 * @marinx/flavors — contrato dos "sabores" e registry.
 *
 * Os flavours nascem um a um, conforme o usuário indicar qual migrar do
 * sang.local. O primeiro é o `marinx` — o portal administrativo, que roda no
 * alvo `admin`.
 */

/**
 * Alvos de build suportados pelo monorepo.
 *
 * `admin` é um site estático servido pelo nginx (sem runtime de servidor: o
 * banco vive no navegador), diferente do `pwa`, que é instalável e offline-first.
 */
export type FlavorTarget = 'admin' | 'pwa' | 'extension' | 'vscode';

/** Configuração de um flavour, compartilhada pelos três alvos. */
export interface FlavorConfig {
  /** Identificador em kebab-case; também é o nome da pasta do flavour. */
  readonly name: string;
  /** Nome exibido ao usuário final (título do app, da extensão, do manifest). */
  readonly displayName: string;
  /** Base da API consumida por este flavour. */
  readonly apiEndpoint: string;
  /** Cor de tema (hex), usada no manifest do PWA e no ícone das extensões. */
  readonly themeColor: string;
  /** Alvos para os quais este flavour é buildado. */
  readonly targets: readonly FlavorTarget[];
  /** Chaves de funcionalidade ligadas/desligadas por flavour. */
  readonly features: Readonly<Record<string, boolean>>;
}

/** Helper de definição — dá inferência e validação de tipo ao declarar um flavour. */
export function defineFlavor(config: FlavorConfig): FlavorConfig {
  return config;
}

/**
 * Portal administrativo — primeiro flavour concreto, migrado de `sang.local/src/Pages`.
 *
 * `apiEndpoint` é vazio de propósito: o admin é estático e fala com o SQLite do
 * próprio navegador; a única rede que ele usa é a API do GitHub na publicação.
 */
export const marinx = defineFlavor({
  name: 'marinx',
  displayName: 'MarinX Admin',
  apiEndpoint: '',
  themeColor: '#0b5fff',
  targets: ['admin'],
  // O que este flavour de fato entrega hoje. `relatorios` é o esqueleto que veio
  // do admin PHP (tela "Em Desenvolvimento"), e por isso conta como entregue.
  features: {
    logs: true,
    configuracoes: true,
    relatorios: true,
    publicarGitHub: true,
  },
});

/**
 * Papiro — segundo flavour concreto, migrado de `sang.local/src/Papiro/Pwa`.
 *
 * `apiEndpoint` aponta para a pasta do conteúdo curado, e não para uma API: o
 * app é offline-first e a única coisa que ele busca na rede é o `manifesto.json`
 * exportado pelo admin, junto dos `dados/*.json` que mudaram desde a última
 * sincronização. Tudo o que o usuário cria fica no SQLite do próprio aparelho.
 */
export const papiro = defineFlavor({
  name: 'papiro',
  displayName: 'Papiro',
  apiEndpoint: './dados',
  themeColor: '#0d6efd',
  targets: ['pwa'],
  // Uma chave por módulo do app. O que está migrado para o monorepo entra como
  // `true`; o restante fica `false` e cai na tela "em breve" — é o registro de
  // progresso da Fase 3, e o que decide o que aparece na home.
  features: {
    anotacoes: true,
    guias: true,
    poesia: true,
    receitas: true,
    jogo: true,
    // Desde a Leva 4.4 todas as cenas existem: os 61 módulos do banco abrem com
    // gráfico, inclusive os três do arquétipo `solar`, que nunca tiveram um.
    criacao: true,
    entenda: true,
    cronologia: true,
    caderno: true,
    prep: true,
    financeiro: true,
    metas: true,
    ministerio: true,
    servico: true,
    estudo: true,
    leitura: true,
    calendario: true,
    perfil: true,
    tutorial: true,
    sobre: true,
  },
});

/**
 * Intellisuite — terceiro flavour concreto, migrado de `sang.local/sang-plugin`.
 *
 * `apiEndpoint` é vazio e sempre será: a extensão não fala com servidor nenhum.
 * A única rede que ela usa é o `post` de uma ação do hub, e esse endereço vem
 * da configuração do usuário (`marinx.baseUrl`), não daqui — um flavour não
 * pode decidir para onde a máquina de outra pessoa manda requisição.
 */
export const intellisuite = defineFlavor({
  name: 'intellisuite',
  displayName: 'Marin-X Intellisuite',
  apiEndpoint: '',
  themeColor: '#64d2ff',
  targets: ['vscode'],
  // Uma chave por módulo da extensão. Diferente dos outros flavours, aqui não é
  // registro de progresso: é o que a extensão entrega hoje. O `forge` (scaffold
  // de PHP/Tempest) e o `errorLens` (vendorizado) ficaram no plugin antigo por
  // decisão explícita, e o `todoTree` foi substituído pelo scanner próprio.
  features: {
    painel: true,
    acoes: true,
    afazeres: true,
    ambiente: true,
    temas: true,
    php: true,
    markdown: true,
    dotenv: true,
    html: true,
    caminhos: true,
    edicao: true,
    forge: false,
    errorLens: false,
  },
});

/**
 * LocalZap — quarto flavour concreto, migrado de `sang.local/src/LocalZap/Extensao`.
 *
 * CRM local-first que roda ao lado do WhatsApp Web. `apiEndpoint` é vazio e é
 * assim que fica: os dados do usuário nunca saem da máquina. Quando a Leva 8
 * trouxer o backend alternativo em Google Planilhas, a URL do Apps Script virá
 * da configuração do próprio usuário, na aba Admin — nunca daqui, pela mesma
 * regra já escrita no `intellisuite`.
 *
 * `themeColor` é o verde do WhatsApp, que já era o padrão de marca do legado.
 */
export const localzap = defineFlavor({
  name: 'localzap',
  displayName: 'LocalZap',
  apiEndpoint: '',
  themeColor: '#25d366',
  targets: ['extension'],
  // Uma chave por aba do dashboard, e é o registro de progresso da Fase 6: a
  // Leva 1 entrega só a fundação, então todas nascem `false` e cada aba liga a
  // sua quando a leva que a escreve fecha. Sem chave ligada, a aba abre no
  // aviso "em breve" — o mesmo desenho do `papiro`.
  features: {
    atendimento: true,
    tarefas: true,
    funil: true,
    clientes: true,
    financeiro: true,
    catalogo: true,
    orcamentos: true,
    faturas: true,
    contratos: true,
    // Ligada na Leva 5 com as áreas de atuação; a Leva 6 acrescentou os dados do
    // negócio, que o PDF exige. O resto da aba (backup, licença dinâmica, o fim
    // da Marca) é a Leva 7.
    admin: true,
  },
});

/** Registry dos flavours conhecidos, indexado por `name`. */
export const flavors: Readonly<Record<string, FlavorConfig>> = {
  marinx,
  papiro,
  intellisuite,
  localzap,
};

/** Busca um flavour pelo nome; retorna `undefined` se não estiver registrado. */
export function getFlavor(name: string): FlavorConfig | undefined {
  return flavors[name];
}

/** Nomes de todos os flavours registrados. */
export function flavorNames(): string[] {
  return Object.keys(flavors);
}
